import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Button } from "@/registry/erbium/ui/button";
import {
  Drawer,
  DrawerClose,
  DrawerPanel,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/registry/erbium/ui/drawer";
export default function DrawerDemo() {
  return (
    <OverlayProvider>
      <Drawer showSwipeHandle>
        <DrawerTrigger render={<Button variant="outline">Open drawer</Button>} />
        <DrawerPanel>
          <DrawerHeader>
            <DrawerTitle>Edit profile</DrawerTitle>
            <DrawerDescription>Make changes and close when finished.</DrawerDescription>
          </DrawerHeader>
          <DrawerContent>Review your profile details here.</DrawerContent>
          <DrawerFooter>
            <DrawerClose render={<Button>Done</Button>} />
          </DrawerFooter>
        </DrawerPanel>
      </Drawer>
    </OverlayProvider>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/overlay-provider-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    layout: "centered",
    docs: { description: { component: "Coordinates drawers and page indentation. Wrap your React app in `OverlayProvider` once so drawers can share their overlay state.\n\n```tsx\nimport { OverlayProvider } from \"@/registry/erbium/ui/overlay-provider\";\n\n<OverlayProvider>{children}</OverlayProvider>;\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Drawer](https://base-ui.com/react/components/drawer)" } },
  },
} satisfies Meta;

export default { ...meta, title: "Providers/Overlay Provider",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/overlay-provider-demo";

const Example = () => <Demo />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}
